import React from "react";
import "../styles/ChatMain.css";

const ChatMain = ({ selectedConversation }) => {
  return (
    <div className="chat-main">
      {selectedConversation ? (
        <>
          <h3>Conversation with {selectedConversation.participantUsernames.find(u => u !== JSON.parse(localStorage.getItem("user"))?.username)}</h3>
          <div className="chat-messages">
            {/* Messages will go here */}
          </div>
          <div className="chat-input">
            <input type="text" placeholder="Type a message..." />
            <button>Send</button>
          </div>
        </>
      ) : (
        <p className="no-convo">No conversation selected</p>
      )}
    </div>
  );
};

export default ChatMain;
